What is the most efficient way to integrate social media sharing buttons on a Go-based website to spread awareness about it?
Here is a Go code snippet that you can use to add social media sharing buttons to your website:
package main
import (
	"net/http"
	"net/url"
)
func main() {
	http.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		http.ServeFile(w, r, "index.html")
	})
	http.HandleFunc("/facebook_share", func(w http.ResponseWriter, r *http.Request) {
		shareURL := r.FormValue("url")
		facebookShareURL := "https://www.facebook.com/sharer/sharer.php?u=" + url.QueryEscape(shareURL)
		http.Redirect(w, r, facebookShareURL, http.StatusSeeOther)
	})
	http.HandleFunc("/twitter_share", func(w http.ResponseWriter, r *http.Request) {
		shareURL := r.FormValue("url")
		shareText := r.FormValue("text")
		twitterHandle := r.FormValue("handle")
		twitterShareURL := "https://twitter.com/share?url=" + url.QueryEscape(shareURL) + "&text=" + url.QueryEscape(shareText) + "&via=" + url.QueryEscape(twitterHandle)
		http.Redirect(w, r, twitterShareURL, http.StatusSeeOther)
	})
	http.HandleFunc("/linkedin_share", func(w http.ResponseWriter, r *http.Request) {
		shareURL := r.FormValue("url")
		shareText := r.FormValue("text")
		linkedinShareURL := "https://www.linkedin.com/shareArticle?url=" + url.QueryEscape(shareURL) + "&title=" + url.QueryEscape(shareText)
		http.Redirect(w, r, linkedinShareURL, http.StatusSeeOther)
	})
	http.ListenAndServe(":8080", nil)
}
Replace the values of shareURL, shareText, and twitterHandle with the corresponding values you want to display in the sharing buttons.
