```html
<!DOCTYPE html>
<html>
<head>
	<title>Scrambled Conversation</title>
</head>
<body>
	<div id="conversation"></div>
	<script>
		function scramble(message) {
			var scrambled = "";
			for (var i = 0; i < message.length; i++) {
				var charCode = message.charCodeAt(i);
				if (charCode >= 65 && charCode <= 90) { // uppercase letters
					charCode = 69 + ((charCode - 65 + 4) % 26);
				} else if (charCode >= 97 && charCode <= 122) { // lowercase letters
					charCode = 101 + ((charCode - 97 + 4) % 26);
				}
				scrambled += String.fromCharCode(charCode);
			}
			return scrambled;
		}
		function unscramble(message) {
			var unscrambled = "";
			for (var i = 0; i < message.length; i++) {
				var charCode = message.charCodeAt(i);
				if (charCode >= 69 && charCode <= 90) { // uppercase letters
					charCode = 65 + ((charCode - 69 - 4 + 26) % 26);
				} else if (charCode >= 101 && charCode <= 122) { // lowercase letters
					charCode = 97 + ((charCode - 101 - 4 + 26) % 26);
				}
				unscrambled += String.fromCharCode(charCode);
			}
			return unscrambled;
		}
		var conversation = [];
		var name = prompt("Enter your name:");
		var message = prompt("Enter your message (type 'quit' to end the conversation):");
		while (message !== "quit") {
			var scrambledMessage = scramble(message);
			conversation.push({name: name, message: scrambledMessage});
			name = prompt("Enter your name:");
			message = prompt("Enter your message (type 'quit' to end the conversation):");
		}
		var conversationDiv = document.getElementById("conversation");
		for (var i = 0; i < conversation.length; i++) {
			var messageObj = conversation[i];
			conversationDiv.innerHTML += "<p><strong>" + messageObj.name + ":</strong> " + messageObj.message + "</p>";
		}
		setTimeout(function() {
			var conversationElements = conversationDiv.getElementsByTagName("p");
			for (var i = 0; i < conversationElements.length; i++) {
				var messageElement = conversationElements[i].getElementsByTagName("strong")[0].nextSibling;
				var unscrambledMessage = unscramble(messageElement.nodeValue.trim());
				messageElement.nodeValue = unscrambledMessage;
			}
		}, 3000);
	</script>
</body>
</html>
```
This code prompts the user to input their name and message, scrambles the message using the provided table, and then displays the conversation on the HTML page. The displayed messages are scrambled, and the user must wait for 3 seconds before the messages unscramble themselves. The unscrambling is done using the same table that was used for scrambling.

