using System;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;
namespace CityInfo
{
    class Program
    {
        static async Task Main(string[] args)
        {
            Console.Write("Enter a city name: ");
            string cityName = Console.ReadLine();

            using var client = new HttpClient();

            var response = await client.GetAsync($"https://api.openweathermap.org/data/2.5/weather?q={cityName}&appid=API_KEY");

            if(response.IsSuccessStatusCode)
            {
                var content = await response.Content.ReadAsStringAsync();
                var weatherInfo = JsonConvert.DeserializeObject<WeatherInfo>(content);

                Console.WriteLine($"City: {weatherInfo.Name}");
                Console.WriteLine($"Country: {weatherInfo.Sys.Country}");
                Console.WriteLine($"Population: {weatherInfo.Population}");
                Console.WriteLine($"Location: {weatherInfo.Coord.Lat}, {weatherInfo.Coord.Lon}");
                Console.WriteLine("Notable attractions:");
                foreach(var attraction in weatherInfo.Attractions)
                {
                    Console.WriteLine(attraction);
                }
            }
            else
            {
                Console.WriteLine($"Error: {response.StatusCode}");
            }
        }
    }

    class WeatherInfo
    {
        public string Name { get; set; }
        public SysInfo Sys { get; set; }
        public int Population { get; set; }
        public CoordInfo Coord { get; set; }
        public string[] Attractions { get; set; }
    }

    class SysInfo
    {
        public string Country { get; set; }
    }

    class CoordInfo
    {
        public float Lat { get; set; }
        public float Lon { get; set; }
    }
}

