```
#include <iostream>
#include <string>
#include <vector>
#include <curl/curl.h>
#include <rapidjson/document.h>
#include <rapidjson/writer.h>
#include <rapidjson/stringbuffer.h>
using namespace std;
using namespace rapidjson;
size_t WriteCallback(void* contents, size_t size, size_t nmemb, void* userp) {
    ((string*)userp)->append((char*)contents, size * nmemb);
    return size * nmemb;
}
vector<string> getSynonyms(string word) {
    vector<string> synonyms;
    string url = "https://api.datamuse.com/words?rel_syn=" + word;
    CURL* curl;
    CURLcode res;
    string readBuffer;
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &readBuffer);
        res = curl_easy_perform(curl);
        curl_easy_cleanup(curl);
        if (res == CURLE_OK) {
            Document d;
            d.Parse(readBuffer.c_str());
            for (Value::ConstValueIterator itr = d.Begin(); itr != d.End(); ++itr) {
                synonyms.push_back(itr->FindMember("word")->value.GetString());
            }
        }
    }
    return synonyms;
}
int main() {
    string pupils = "pupils";
    string apprehensive = "apprehensive";
    string lift = "lift";
    string arms = "arms";
    vector<string> pupilsSynonyms = getSynonyms(pupils);
    vector<string> apprehensiveSynonyms = getSynonyms(apprehensive);
    vector<string> liftSynonyms = getSynonyms(lift);
    vector<string> armsSynonyms = getSynonyms(arms);
